      order by "tags"."id"
    ) as "tags" from "file_tags" inner join "tags" on "file_tags"."tag_id" = "tags"."id" group by "file_tags"."file_id") "tags_by_file" on "tags_by_file"."file_id" = "files"."id" order by "files"."id"

